#!/usr/bin/env node
// Fails when the committed Gemini CLI commands differ from a fresh generation
// (#1249).
//
// `agents/commands/gemini-cli/harness/*.toml` are generated by
// `harness generate-slash-commands`, which inlines each skill's whole SKILL.md
// into the command, and every file is headed "Do not edit". Nothing ever
// regenerated them or checked them: they sat unchanged from 2026-07-19 while
// their SKILL.md sources moved on (#1125 among others), and six skills never
// got a Gemini command at all. Gemini users were reading months-old
// instructions, and every surface was green, because nothing measured it.
//
// How: copy `agents/skills/claude-code` into a temp dir shaped like the repo,
// run the generator there with exactly the in-repo invocation, and compare its
// `agents/commands/gemini-cli/harness/` with the committed one, file by file
// and in both directions (changed, missing, stale). Generating into a scratch
// tree rather than with `--output` is deliberate: with `--output` every
// platform shares one directory and each platform's pass deletes the previous
// one's files, so the result depends on platform order. `--skills-dir-only`
// keeps globally-installed skills out of a repo-owned artifact (#704).
//
// Only the gemini-cli half is checked or written. The generator also emits the
// claude-code commands; their drift is tracked separately.
//
// The generator is the harness CLI, resolved as `$HARNESS_BIN` (default
// `harness` on PATH). CI runs this with the pinned `$HARNESS_CLI` major; a new
// minor of that major can change the template and red this gate with no change
// here, so every message names the generator version it measured with.
//
// Exit codes follow the repo's gate convention (#508):
//   0 = every generated command is committed, byte for byte, and nothing else
//   1 = DRIFT — changed, missing or stale files; the message gives the
//       regenerate command
//   2 = usage error
//   3 = ABSTENTION — the generator is not installed, exited non-zero, or
//       emitted zero commands, or there is no skills tree. "0 of 0 match" is
//       not a pass, and neither is a check that could not run.
//
//   node scripts/gemini-commands-drift.mjs [--root <dir>] [--write]
import { spawnSync } from 'node:child_process';
import {
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { isMain } from './lib/is-main.mjs';

const SKILLS_DIR = join('agents', 'skills', 'claude-code');
const OUT_DIR = join('agents', 'commands', 'gemini-cli', 'harness');
const REGEN = 'node scripts/gemini-commands-drift.mjs --write';
const GENERATE_ARGS = [
  'generate-slash-commands',
  '--skills-dir',
  SKILLS_DIR,
  '--skills-dir-only',
  '--yes',
];

class Abstain extends Error {}

/** `{ name: contents }` for every .toml directly under `dir`. */
function readCommands(dir) {
  if (!existsSync(dir)) return {};
  const files = readdirSync(dir).filter((f) => f.endsWith('.toml'));
  return Object.fromEntries(
    files.map((f) => [f, readFileSync(join(dir, f), 'utf-8')]),
  );
}

function generatorVersion(bin) {
  const r = spawnSync(bin, ['--version'], { encoding: 'utf-8' });
  return r.error ? 'unknown' : String(r.stdout).trim().split('\n').pop();
}

/** Runs the generator in a scratch copy of the skills tree. */
function generate(root, bin) {
  const skills = join(root, SKILLS_DIR);
  if (!existsSync(skills) || readdirSync(skills).length === 0) {
    throw new Abstain(`no skills to generate from at ${SKILLS_DIR}`);
  }
  const scratch = mkdtempSync(join(tmpdir(), 'gemini-commands-'));
  try {
    cpSync(skills, join(scratch, SKILLS_DIR), { recursive: true });
    const r = spawnSync(bin, GENERATE_ARGS, {
      cwd: scratch,
      encoding: 'utf-8',
    });
    if (r.error) {
      throw new Abstain(`generator '${bin}' is unavailable (${r.error.code})`);
    }
    if (r.status !== 0) {
      throw new Abstain(
        `generator exited ${r.status}:\n${r.stdout}${r.stderr}`.trimEnd(),
      );
    }
    return readCommands(join(scratch, OUT_DIR));
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}

/** Every difference between the generated and committed sets, sorted. */
export function diffCommands(generated, committed) {
  const names = [
    ...new Set([...Object.keys(generated), ...Object.keys(committed)]),
  ].sort();
  const out = [];
  for (const name of names) {
    if (!(name in committed)) out.push(`missing: ${name}`);
    else if (!(name in generated)) out.push(`stale: ${name}`);
    else if (generated[name] !== committed[name]) out.push(`changed: ${name}`);
  }
  return out;
}

/** Replaces the committed set with the generated one. */
function writeCommands(dir, generated) {
  mkdirSync(dir, { recursive: true });
  for (const name of Object.keys(readCommands(dir))) {
    if (!(name in generated)) rmSync(join(dir, name));
  }
  for (const [name, body] of Object.entries(generated)) {
    writeFileSync(join(dir, name), body, 'utf-8');
  }
}

function parseArgs(argv) {
  const opts = { root: join(dirname(fileURLToPath(import.meta.url)), '..') };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--write') opts.write = true;
    else if (argv[i] === '--root' && argv[i + 1]) opts.root = argv[++i];
    else return null;
  }
  return opts;
}

function run(opts, bin) {
  const version = generatorVersion(bin);
  const generated = generate(opts.root, bin);
  const total = Object.keys(generated).length;
  if (total === 0) {
    throw new Abstain(`generator (harness ${version}) emitted 0 commands`);
  }
  const committedDir = join(opts.root, OUT_DIR);
  if (opts.write) {
    writeCommands(committedDir, generated);
    console.log(`Wrote ${total} gemini-cli commands (harness ${version}).`);
    return 0;
  }
  const drift = diffCommands(generated, readCommands(committedDir));
  if (drift.length === 0) {
    console.log(
      `${total} of ${total} gemini-cli commands match a fresh generation ` +
        `(harness ${version}).`,
    );
    return 0;
  }
  console.log(
    `::error::${OUT_DIR} has drifted from a fresh generation ` +
      `(harness ${version}):\n  ${drift.join('\n  ')}\n` +
      `Regenerate with: ${REGEN}`,
  );
  return 1;
}

function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (!opts) {
    console.error('usage: gemini-commands-drift.mjs [--root <dir>] [--write]');
    process.exit(2);
  }
  const bin = process.env.HARNESS_BIN || 'harness';
  try {
    process.exit(run(opts, bin));
  } catch (err) {
    if (!(err instanceof Abstain)) throw err;
    console.log(`ABSTAINED: ${err.message}. Nothing was checked.`);
    process.exit(3);
  }
}

if (isMain(import.meta.url)) {
  main();
}
